from __future__ import annotations

import json
from pathlib import Path
from src.project_paths import resolve_project_path
from typing import Any

from src.lifelong_learning.agents.base import Agent
from src.lifelong_learning.core.models import (
    ChatHistory, ChatMessage, Role
)


class OfflineOracleAgent(Agent):
    """Deterministic offline Agent generated by GT data"""

    def __init__(self, oracle_data_file_path: str | Path) -> None:
        oracle_data_file_path = resolve_project_path(oracle_data_file_path)
        with oracle_data_file_path.open("r", encoding="utf-8") as file:
            oracle_dataset: dict[str, dict[str, Any]] = json.load(file)
        
        self.response_dict: dict[str, tuple[str, str]] = {}

        for entry in oracle_dataset.values():
            instruction = entry["instruction"]
            operation_response = self._build_operation_response(
                entry["sql"]
            )
            finish_response = self._build_finish_response(entry)

            self.response_dict[instruction] = (
                operation_response,
                finish_response
            )
    
    @staticmethod
    def _build_operation_response(sql: str) -> str:
        """Construct an Agent response that requests DBBench to execute SQL"""
        return (
            "Think: Execute the ground truth SQL for offline verification.\n"
            "Action: Operation\n"
            f"```sql\n{sql}\n```"
        )
    
    @staticmethod
    def _build_finish_response(entry: dict[str, Any]) -> str:
        """Construct a final response after SQL execution"""

        answer_direct = entry["answer_direct"]
        if answer_direct is not None:
            final_answer = str(
                [
                    tuple(row)
                    for row in answer_direct
                ]
            )
        else:
            final_answer = entry["answer_md5"]
        return (
            "Think: Submit the verified result.\n"
            "Action: Answer\n"
            f"Final Answer: {final_answer}"
        )
    
    def _find_current_instruction(self, chat_history: ChatHistory) -> str:
        """Locates current Case according to the latest user task info"""
        for message in reversed(chat_history.messages):
            if message.role != Role.USER:
                continue
            for instruction in self.response_dict:
                if instruction in message.content:
                    return instruction
        raise ValueError(
            "OfflineOracleAgent cannot find the current instruction"
        )
    
    def inference(self, chat_history: ChatHistory) -> ChatMessage:
        """1. Return GT SQL; 2. Return final standard answer"""
        instruction = self._find_current_instruction(chat_history)
        operation_response, finish_response = (
            self.response_dict[instruction]
        )
        operation_already_sent = any(
            message.role == Role.AGENT
            and message.content == operation_response
            for message in chat_history.messages
        )
        if operation_already_sent:
            response_content = finish_response
        else:
            response_content = operation_response
        
        return ChatMessage(
            role=Role.AGENT,
            content=response_content
        )